defmodule SuchConfigCore.Generators.AIContextGenerator do
  @moduledoc """
  Generates AI context files (CLAUDE.md, .cursorrules, AGENTS.md) from project analysis.

  This module transforms parsed project data into structured markdown files
  that help AI coding assistants (Claude, Cursor, etc.) understand and work
  effectively with the project.

  ## Architecture

  The generator uses a modular architecture with language-specific submodules:

  - `AIContext.Common` - Shared sections (header, footer, contributing, etc.)
  - `AIContext.Python` - Python-specific generation (FastAPI, Django, Flask)
  - `AIContext.Node` - Node.js/TypeScript-specific generation (Next.js, React)
  - `AIContext.FrameworkPractices` - Framework best practices
  - `AIContext.Helpers` - Utility functions

  ## Output Formats

  - **:ai_context** - Universal AI context file (CLAUDE.md, .cursorrules, AGENTS.md)
  - **:suchconfig** - Team-shareable configuration template

  ## Design Philosophy

  Generated context files are:
  - **Deterministic** - Same input always produces same output
  - **Comprehensive** - Includes all detected patterns and configurations
  - **Up-to-date** - Regenerate anytime to reflect project changes
  - **Structured** - Consistent format that AI tools can parse reliably
  """

  alias SuchConfigCore.Generators.AIContext.{Common, Python, Node, Ruby, Go, Contributing, StackDetails, Helpers}

  @doc """
  Generates an AI context file from project data.

  ## Parameters

  - `project_data` - Parsed project data from ProjectParser
  - `format` - Output format (:ai_context, :claude_md, :cursorrules, :suchconfig)
  - `options` - Optional configuration overrides

  ## Returns

  - `{:ok, content}` - Generated markdown/text content
  - `{:error, reason}` - Error if generation fails

  ## Examples

      iex> generate(project_data, :ai_context)
      {:ok, "# my-project\\n\\n> Auto-generated by SuchConfig..."}
  """
  def generate(project_data, format \\ :ai_context, options \\ %{})

  def generate(project_data, :ai_context, options) do
    {:ok, build_ai_context(project_data, options)}
  end

  def generate(project_data, :claude_md, options) do
    {:ok, build_ai_context(project_data, options)}
  end

  def generate(project_data, :cursorrules, options) do
    {:ok, build_ai_context(project_data, options)}
  end

  def generate(project_data, :suchconfig, options) do
    {:ok, build_suchconfig_template(project_data, options)}
  end

  def generate(project_data, :contributing, _options) do
    Contributing.generate(project_data)
  end

  def generate(project_data, :stack_details, _options) do
    StackDetails.generate(project_data)
  end

  defp build_ai_context(project_data, _options) do
    project_type = project_data[:project_type]

    sections = [
      Common.build_header(project_data),
      Common.build_overview(project_data),
      build_tech_stack_section(project_data),
      build_quick_start_section(project_data),
      Common.build_project_structure(project_data),
      build_dependencies_section(project_data),
      build_framework_practices_section(project_data),
      Common.build_agents_commands(project_data),
      build_development_commands_section(project_data),
      Common.build_pre_commit_hooks(project_data),
      Common.build_ci_cd(project_data),
      Common.build_agents_code_style(project_data),
      Common.build_contributing(project_data),
      Common.build_security(project_data),
      Common.build_coding_standards(project_data),
      Common.build_testing(project_data),
      Common.build_git_workflow(project_data),
      Common.build_key_files(project_data),
      build_restrictions_section(project_data, project_type),
      Common.build_footer()
    ]

    sections
    |> Enum.reject(fn s -> is_nil(s) or s == "" end)
    |> Enum.join("\n\n")
  end

  defp build_tech_stack_section(project_data) do
    project_type = project_data[:project_type]

    base_items = build_base_tech_stack(project_data)

    language_items =
      case project_type do
        :python -> Python.build_tech_stack(project_data)
        :node -> Node.build_tech_stack(project_data)
        :ruby -> Ruby.build_tech_stack(project_data)
        :mixed_ruby -> Ruby.build_tech_stack(project_data)
        :go -> Go.build_tech_stack(project_data)
        _ -> []
      end

    all_items = base_items ++ language_items

    if length(all_items) > 0 do
      """
      ## Tech Stack

      #{Enum.join(all_items, "\n")}
      """
    else
      nil
    end
  end

  defp build_base_tech_stack(project_data) do
    project_type = project_data[:project_type]
    items = []

    items =
      case project_data[:monorepo_config] do
        %{is_monorepo: true, tool: tool} when not is_nil(tool) ->
          items ++ ["- **Monorepo**: #{Helpers.format_monorepo_tool(tool)}"]

        _ ->
          items
      end

    code_quality = project_data[:code_quality] || %{}
    testing_config = project_data[:testing_config] || %{}

    items =
      if project_type in [:ruby, :mixed_ruby, :python] do
        items
      else
        case code_quality do
          %{has_linting: true, eslint: eslint} when not is_nil(eslint) -> items ++ ["- **Linting**: ESLint"]
          %{has_linting: true, biome: true} -> items ++ ["- **Linting**: Biome"]
          _ -> items
        end
      end

    items =
      if project_type in [:ruby, :mixed_ruby, :python] do
        items
      else
        case code_quality do
          %{has_formatting: true, prettier: true} -> items ++ ["- **Formatting**: Prettier"]
          %{has_formatting: true, biome: true} -> items ++ ["- **Formatting**: Biome"]
          _ -> items
        end
      end

    items =
      if project_type in [:ruby, :mixed_ruby, :python] do
        items
      else
        case testing_config do
          %{frameworks: frameworks} when is_list(frameworks) and length(frameworks) > 0 ->
            items ++ ["- **Testing**: #{Enum.map_join(frameworks, ", ", &Helpers.format_test_framework/1)}"]

          _ ->
            items
        end
      end

    items
  end

  defp build_quick_start_section(project_data) do
    case project_data[:project_type] do
      :python -> Python.build_quick_start(project_data)
      :node -> Node.build_quick_start(project_data)
      :ruby -> Ruby.build_quick_start(project_data)
      :mixed_ruby -> Ruby.build_quick_start(project_data)
      :go -> Go.build_quick_start(project_data)
      _ -> nil
    end
  end

  defp build_dependencies_section(project_data) do
    case project_data[:project_type] do
      :python -> Python.build_dependencies(project_data)
      :node -> Node.build_dependencies(project_data)
      :ruby -> Ruby.build_dependencies(project_data)
      :mixed_ruby -> Ruby.build_dependencies(project_data)
      :go -> Go.build_dependencies(project_data)
      _ -> nil
    end
  end

  defp build_framework_practices_section(project_data) do
    case project_data[:project_type] do
      :python -> Python.build_framework_practices(project_data)
      :node -> Node.build_framework_practices(project_data)
      :ruby -> Ruby.build_framework_practices(project_data)
      :mixed_ruby -> Ruby.build_framework_practices(project_data)
      :go -> Go.build_framework_practices(project_data)
      _ -> nil
    end
  end

  defp build_development_commands_section(project_data) do
    make_targets = project_data[:make_targets] || []

    npm_commands = Node.build_commands(project_data)

    make_commands =
      make_targets
      |> Enum.take(10)
      |> Enum.map(fn target ->
        "| `make #{target}` | #{Helpers.describe_make_target(target)} |"
      end)

    python_commands =
      if project_data[:project_type] == :python do
        Python.build_commands(project_data)
      else
        []
      end

    ruby_commands =
      if project_data[:project_type] in [:ruby, :mixed_ruby] do
        Ruby.build_commands(project_data)
      else
        []
      end

    go_commands =
      if project_data[:project_type] == :go do
        Go.build_commands(project_data)
      else
        []
      end

    all_commands = npm_commands ++ make_commands ++ python_commands ++ ruby_commands ++ go_commands

    if length(all_commands) > 0 do
      """
      ## Development Commands

      | Command | Description |
      |---------|-------------|
      #{Enum.join(all_commands, "\n")}
      """
    else
      nil
    end
  end

  defp build_restrictions_section(project_data, project_type) do
    ai_context = project_data[:ai_context_files] || %{}
    files = project_data[:files] || []

    restrictions =
      case project_type do
        :python -> Python.build_restrictions()
        :ruby -> Ruby.build_restrictions()
        :mixed_ruby -> Ruby.build_restrictions()
        :go -> Go.build_restrictions()
        :elixir -> build_elixir_restrictions()
        :rust -> build_rust_restrictions()
        _ -> Node.build_restrictions()
      end

    restrictions =
      if Helpers.has_file?(files, :prisma_schema) do
        restrictions ++ ["- `prisma/migrations/` - Database migration history"]
      else
        restrictions
      end

    restrictions =
      if ai_context[:has_cursorignore] do
        restrictions ++ ["- See `.cursorignore` for additional patterns"]
      else
        restrictions
      end

    caution_items =
      case project_type do
        :python -> Python.build_caution_items()
        :ruby -> Ruby.build_caution_items()
        :mixed_ruby -> Ruby.build_caution_items()
        :go -> Go.build_caution_items()
        _ -> Node.build_caution_items()
      end

    """
    ## Restrictions

    Do not edit these files/directories:

    #{Enum.join(restrictions, "\n")}

    Be cautious with:

    #{Enum.join(caution_items, "\n")}
    """
  end

  defp build_elixir_restrictions do
    [
      "- `_build/`, `deps/` - Build outputs and dependencies",
      "- `.elixir_ls/` - Language server cache",
      "- `priv/static/` - Compiled assets",
      "- `.git/` - Git internals"
    ]
  end

  defp build_rust_restrictions do
    [
      "- `target/` - Build outputs",
      "- `Cargo.lock` - Lock file (for libraries)",
      "- `.git/` - Git internals"
    ]
  end

  defp build_suchconfig_template(project_data, _options) do
    """
    version: 1

    project:
      name: "#{project_data[:project_name] || "Project"}"
      description: "#{extract_description(project_data)}"
      # team: "Your Team Name"

    setup:
      prerequisites:
        # - "Custom prerequisite steps"

      custom_steps: []
        # - title: "Custom Step"
        #   command: "your-command"
        #   description: "What this step does"

    conventions:
      branching:
        pattern: "feature|fix|chore|docs/{description}"
        main_branch: "main"

      commits:
        format: "conventional"
        # scopes: ["api", "ui", "db"]

    #{build_suchconfig_env_vars(project_data)}

    resources: []
      # - name: "Documentation"
      #   url: "https://..."

    restrictions:
      readonly_files:
        - "node_modules/**"
        - "dist/**"
        - ".git/**"

      no_ai_edit:
        - ".env*"
        - "*.pem"
        - "*.key"
    """
  end

  defp build_suchconfig_env_vars(project_data) do
    env_vars = project_data[:env_vars] || []

    if length(env_vars) > 0 do
      vars =
        env_vars
        |> Enum.take(10)
        |> Enum.map_join("", fn var ->
          key = var[:key] || "UNKNOWN"

          """
            #{key}:
              description: "Configure this value"
              required: true
          """
        end)

      "env_vars:\n#{vars}"
    else
      "env_vars: {}"
    end
  end

  defp extract_description(project_data) do
    files = project_data[:files] || []
    package_json = Helpers.find_file(files, :package_json)
    pyproject = Helpers.find_file(files, :pyproject)
    readme = Helpers.find_file(files, :readme)

    cond do
      package_json && package_json[:description] -> package_json[:description]
      pyproject && pyproject[:description] -> pyproject[:description]
      readme && readme[:title] -> readme[:title]
      true -> nil
    end
  end
end
